import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import { cacheLife } from 'next/cache'

async function getStories() {
  'use cache'
  cacheLife({ stale: 3600, revalidate: 3600, expire: 86400 })
  await new Promise((resolve) => setTimeout(resolve, 80))
  return ['City council approves new park', 'Night market opens Friday']
}

export default async function NewsPage() {
  const stories = await getStories()

  return (
    <main>
      <h1>Newsroom</h1>
      {stories.map((story) => (
        <article key={story}>{story}</article>
      ))}
    </main>
  )
}

import { cookies } from 'next/headers'
import { Suspense } from 'react'

export default function PreviewPage() {
  return (
    <main>
      <h1>Editor preview</h1>
      <Suspense fallback={<p>Loading draft...</p>}>
        <DraftTitle />
      </Suspense>
    </main>
  )
}

async function DraftTitle() {
  const draft = (await cookies()).get('draft-title')?.value ?? 'Untitled draft'

  return <p>{draft}</p>
}
